package io.knowledgebrain.activity;
import java.util.*;import java.security.SecureRandom;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.activity.api.enabled",havingValue="true")
final class ActivityController {
 record Page(UUID spaceId,String timezone,String kind,String consistency,List<ActivityEvent> items,String nextBefore){}
 private final ActivityStore store;private final ActivityClickHouse index;private final SpaceAuthorizationClient authority;private final MeterRegistry metrics;private final SecureRandom random=new SecureRandom();
 ActivityController(ActivityStore store,@org.springframework.beans.factory.annotation.Qualifier("activityReader") ActivityClickHouse index,SpaceAuthorizationClient authority,MeterRegistry metrics){this.store=store;this.index=index;this.authority=authority;this.metrics=metrics;}
 private String parent(HttpServletRequest r){String value=r.getHeader("traceparent");if(value!=null&&value.matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")&&!value.substring(3,35).equals("0".repeat(32))&&!value.substring(36,52).equals("0".repeat(16)))return value;byte[] a=new byte[16],b=new byte[8];random.nextBytes(a);random.nextBytes(b);return "00-"+HexFormat.of().formatHex(a)+"-"+HexFormat.of().formatHex(b)+"-01";}
 @GetMapping("/api/spaces/{spaceId}/activity/timeline") ResponseEntity<Page> timeline(@PathVariable String spaceId,HttpServletRequest r){UUID space=ActivityEvent.id(spaceId);if(!r.isSecure()||r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Empty HTTPS read required");var q=ActivityQuery.parse(space,r.getParameterMap());String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ambiguous session");token=c.getValue();}authority.authorize(space,token,parent(r));var state=store.state();if(!state.seeded()||state.rebuilding()||!state.ready())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Timeline projection is recovering");var rows=index.list(space,q);var items=List.copyOf(rows.subList(0,Math.min(rows.size(),q.limit())));metrics.counter("brain.activity.reads","kind",q.kind()).increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(space,q.timezone(),q.kind(),"EVENTUAL",items,rows.size()>q.limit()?q.cursor(items.getLast()):null));}
}
